/**
 * Error thrown by assert() when an assertion fails.
 *
 * In Dart, AssertionError is thrown when an assert statement fails.
 * This is typically only in debug/development mode.
 */
export class AssertionError extends Error {
  /**
   * Creates an AssertionError.
   * @param {string|null} message - The assertion message
   */
  constructor(message) {
    super(message || 'Assertion failed');
    this.name = 'AssertionError';
  }
}
